-- The session and token test tables for a PostgreSQL copy of the InvoiceSystem sample. Settings:
-- ApiAuth=true, UserTable=Employee, UserNameColumn=Login, UserRoleColumn=IsManager, UserAdminColumn=IsAdministrator,
-- TokenTables=AuthToken:TokenHash:ExpiresOn:UsedOn+RevokedOn:FamilyId, TokenAnonymousSpend=AuthToken
-- The seed hashes are in capitals on purpose: a case-sensitive database must still find a token.
CREATE TABLE IF NOT EXISTS "Employee" (
    "EmployeeId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" varchar(50) NOT NULL,
    "IsManager" boolean NOT NULL DEFAULT false,
    "Login" varchar(50) NULL,
    "PasswordHash" varchar(200) NULL,
    "IsAdministrator" boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS "AuthToken" (
    "AuthTokenId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "EmployeeId" integer NOT NULL REFERENCES "Employee" ("EmployeeId"),
    "Kind" varchar(20) NOT NULL CHECK ("Kind" IN ('verify', 'reset', 'refresh', 'session')),
    "TokenHash" varchar(128) NOT NULL,
    "FamilyId" varchar(40) NULL,
    "CreatedOn" timestamp NOT NULL,
    "ExpiresOn" timestamp NOT NULL,
    "UsedOn" timestamp NULL,
    "RevokedOn" timestamp NULL
);

INSERT INTO "Employee" ("Name", "IsManager", "Login", "IsAdministrator")
SELECT 'Joe Doe', true, 'jdoe', true WHERE NOT EXISTS (SELECT 1 FROM "Employee");
INSERT INTO "Employee" ("Name", "IsManager", "Login", "IsAdministrator")
SELECT 'Ann Kim', false, 'akim', false WHERE (SELECT count(*) FROM "Employee") = 1;

INSERT INTO "AuthToken" ("EmployeeId", "Kind", "TokenHash", "FamilyId", "CreatedOn", "ExpiresOn")
SELECT 1, 'refresh', 'E6D451559BC1627DC28CFC5FE5D890EC331826F1B188B939005B2564721F7E0D', 'seed-family', now(), now() + interval '30 days'
WHERE NOT EXISTS (SELECT 1 FROM "AuthToken");
